entries[6940] = { ["name"] = "Segen der Aufopferung", ["text"] = "1.4% von Grundmana 40 Meter Reichweite\nSofort 2 min Abklingzeit\nVergeltung\nSegnet ein Gruppen- oder Schlachtzugsmitglied und verringert seinen erlittenen Schaden um 20%, jedoch erleidet Ihr 100% des verhinderten Schadens.\n\nHält 12 Sek. lang an oder bis der umgelenkte Schaden Euch unter 20% Eurer Gesundheit fallen lassen würde.\n\nHeilig, Schutz\nSegnet ein Gruppen- oder Schlachtzugsmitglied und verringert seinen erlittenen Schaden um 30%, jedoch erleidet Ihr 100% des verhinderten Schadens.\n\nHält 12 Sek. lang an oder bis der umgelenkte Schaden Euch unter 20% Eurer Gesundheit fallen lassen würde." }
