entries[7953] = { ["name"] = "Deviatschuppenumhang", ["text"] = "Wirken in 2 sek.\nReagenzien:\nDeviatschuppe (4), Geschmeidiger leichter Balg , Feiner Faden\nOptionale Reagenzien:\n[] (#31)\nBeute von:\nDruide des Giftzahns\nZone:\nHöhlen des Wehklagens\n\nDeviatschuppenumhang\nWird beim Anlegen gebunden\nRücken\n2 Rüstung\n+2 Beweglichkeit\n+2 Ausdauer\n6" }
